N KEY (parent_tenant_id) REFERENCES tenants(id)"},{"name":"tenants_pkey","relation":"tenants","definition":"PRIMARY KEY (id)"},{"name":"tenants_royalty_type_check","relation":"tenants","definition":"CHECK (royalty_type::text = ANY (ARRAY['fixed'::character varying::text, 'percentage'::character varying::text]))"},{"name":"tenants_status_check","relation":"tenants","definition":"CHECK (status = ANY (ARRAY['active'::text, 'suspended'::text, 'terminated'::text]))"},{"name":"users_email_key","relation":"users","definition":"UNIQUE (email)"},{"name":"users_pkey","relation":"users","definition":"PRIMARY KEY (id)"},{"name":"users_position_tier_check","relation":"users","definition":"CHECK (position_tier = ANY (ARRAY['junior'::text, 'senior'::text, 'lead'::text]))"},{"name":"users_role_check","relation":"users","definition":"CHECK (role = ANY (ARRAY['admin'::text, 'ktv_lead'::text, 'ktv'::text, 'admin_staff'::text, 'accountant'::text, 'hr'::text, 'student'::text]))"},{"name":"users_tenant_id_fkey","relation":"users","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id)"}],"defaultAcls":[{"acl":"{postgres=r*w*U*/supabase_admin}","kind":"S","role":"supabase_admin","schema":"extensions"},{"acl":"{postgres=X*/supabase_admin}","kind":"f","role":"supabase_admin","schema":"extensions"},{"acl":"{postgres=a*r*w*d*D*x*t*m*/supabase_admin}","kind":"r","role":"supabase_admin","schema":"extensions"},{"acl":"{postgres=rwU/supabase_admin,dashboard_user=rwU/supabase_admin}","kind":"S","role":"supabase_admin","schema":"realtime"},{"acl":"{postgres=X/supabase_admin,dashboard_user=X/supabase_admin}","kind":"f","role":"supabase_admin","schema":"realtime"},{"acl":"{postgres=a*r*wdDxtm/supabase_admin,dashboard_user=arwdDxtm/supabase_admin}","kind":"r","role":"supabase_admin","schema":"realtime"},{"acl":"{postgres=rwU/supabase_admin,anon=rwU/supabase_admin,authenticated=rwU/supabase_admin,service_role=rwU/supabase_admin}","kind":"S","role":"supabase_admin","schema":"graphql_public"},{"acl"