ashboard_user=arwdDxtm/supabase_auth_admin}","kind":"r","role":"supabase_auth_admin","schema":"auth"}],"memberships":[{"role":"pg_monitor","admin":true,"member":"postgres"},{"role":"pg_monitor","admin":false,"member":"supabase_etl_admin"},{"role":"pg_monitor","admin":false,"member":"supabase_read_only_user"},{"role":"pg_read_all_settings","admin":false,"member":"pg_monitor"},{"role":"pg_read_all_stats","admin":false,"member":"pg_monitor"},{"role":"pg_stat_scan_tables","admin":false,"member":"pg_monitor"},{"role":"pg_signal_backend","admin":true,"member":"postgres"},{"role":"pg_read_all_data","admin":true,"member":"postgres"},{"role":"pg_read_all_data","admin":false,"member":"supabase_etl_admin"},{"role":"pg_read_all_data","admin":false,"member":"supabase_read_only_user"},{"role":"pg_create_subscription","admin":true,"member":"postgres"},{"role":"postgres","admin":false,"member":"cli_login_postgres"},{"role":"anon","admin":true,"member":"postgres"},{"role":"anon","admin":false,"member":"authenticator"},{"role":"authenticated","admin":true,"member":"postgres"},{"role":"authenticated","admin":false,"member":"authenticator"},{"role":"service_role","admin":true,"member":"postgres"},{"role":"service_role","admin":false,"member":"authenticator"},{"role":"authenticator","admin":true,"member":"postgres"},{"role":"authenticator","admin":false,"member":"supabase_storage_admin"},{"role":"supabase_privileged_role","admin":false,"member":"postgres"},{"role":"supabase_privileged_role","admin":false,"member":"supabase_etl_admin"}],"serverVersion":"170006"}$expected$::jsonb THEN RAISE EXCEPTION 'E2E_BASELINE_DRIFT'; END IF; END $baseline$;
DO $dependency$ DECLARE actual jsonb; BEGIN SELECT evidence-'readOnly' INTO actual FROM (SELECT jsonb_build_object(
 'readOnly',current_setting('transaction_read_only'),
 'functions',(SELECT jsonb_agg(jsonb_build_object('signature',p.oid::regprocedure::text,'definition',pg_get_functiondef(p.oid),'owner',pg_get_userbyid(p.proowner),'definer',p.prosecdef,'acl',p.proacl::text,'config',p.proconfig) ORDER BY p.oid::regprocedure::text)
 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('edu_capture_enrollment_created_event','preschool_course_assignment_visible','update_updated_at_column','update_persons_updated_at','is_admin','is_hr','is_accountant','is_hq_super_admin')),
 'triggerDependencies',(SELECT coalesce(jsonb_agg(jsonb_build_object('dependent',t.tgname,'table',t.tgrelid::regclass::text,'function',t.tgfoid::regprocedure::text)),'[]') FROM pg_trigger t WHERE NOT t.tgisinternal AND t.tgrelid='public.edu_enrollments'::regclass),
