:"CREATE TRIGGER trg_people_directory_updated_at BEFORE UPDATE ON public.people_directory FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()"},{"name":"trigger_persons_updated_at","function":"update_persons_updated_at()","relation":"persons","definition":"CREATE TRIGGER trigger_persons_updated_at BEFORE UPDATE ON public.persons FOR EACH ROW EXECUTE FUNCTION update_persons_updated_at()"},{"name":"audit_tenants_changes","function":"log_audit_event()","relation":"tenants","definition":"CREATE TRIGGER audit_tenants_changes AFTER INSERT OR DELETE OR UPDATE ON public.tenants FOR EACH ROW EXECUTE FUNCTION log_audit_event()"},{"name":"update_tenants_updated_at","function":"update_updated_at_column()","relation":"tenants","definition":"CREATE TRIGGER update_tenants_updated_at BEFORE UPDATE ON public.tenants FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()"},{"name":"audit_users_changes","function":"log_audit_event()","relation":"users","definition":"CREATE TRIGGER audit_users_changes AFTER INSERT OR DELETE OR UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION log_audit_event()"},{"name":"update_users_updated_at","function":"update_updated_at_column()","relation":"users","definition":"CREATE TRIGGER update_users_updated_at BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION update_updated_at_column()"}],"functions":[{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"8cb9c457e4d4d71b5d56df6ed01ceefb","owner":"postgres","config":null,"definer":true,"signature":"current_tenant_id()","definition":"CREATE OR REPLACE FUNCTION public.current_tenant_id()\n RETURNS uuid\n LANGUAGE sql\n STABLE SECURITY DEFINER\nAS $function$\n  SELECT tenant_id FROM public.users WHERE id = auth.uid();\n$function$\n"},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"365d8ec3a2e5a7c787ca4129e2550d55","owner":"postgres","config":null,"definer":true,"signature":"current_user_role()","definition":"CREATE OR REPLACE FUNCTION public.current_user_role()\n RETURNS text\n LANGUAGE sql\n STABLE SECURITY DEFINER\nAS $function$\n  SELECT role FROM public.users WHERE id = auth.uid();\n$function$\n"},{"acl":"{postgres=X/postgres,service_role=X/postgres}","md5":"53128a40b63d36211cdcd505ed3791be","owner":"postgres","config":["search_path=\"\""],"definer":true,"signature":"edu_set_daily_attendance(uuid,uuid,text,timestamp with time zone,date)","definition":"CREATE OR REPLACE FUNCTION public.edu_set_daily_attendance(p_tenant_id uuid, p_enrollment_id uuid, p_status text, p_roll_call_time timestamp with time zone, p_school_day date)\n RETURNS TABLE(id uuid, tenant_id uuid, enrollment_id uuid, school_day date, status text, event_id uuid, roll_call_time timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone)\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO ''\nAS $function$\nDECLARE v_event_id uuid; v_state public.edu_attendance_daily_state%ROWTYPE;\nBEGIN\n  IF auth.role() IS DISTINCT FROM 'service_role' THEN\n    RAISE EXCEPTION 'ATTENDANCE_TRUSTED_SERVER_REQUIRED' USING ERRCODE='42501';\n  END IF;\n  IF p_tenant_id IS NULL OR p_enrollment_id IS NULL OR p_status IS NULL\n    OR p_status NOT IN ('present','absent','excused') OR p_roll_call_time IS NULL OR p_school_day IS NULL THEN\n    RAISE EXCEPTION 'ATTENDANCE_INPUT_INVALID' USING ERRCODE='22023';\n  END IF;\n  PERFORM pg_advisory_xact_lock(hashtextextended('education-attendance:'||p_tenant_id::text||':'||p_enrollment_id::text||':'||p_school_day::text,0));\n  PERFORM 1 FROM public.edu_enrollments e WHERE e.id=p_enrollment_id AND e.tenant_id=p_tenant_id FOR KEY SHARE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'ATTENDANCE_ENROLLMENT_NOT_FOUND' USING ERRCODE='P0002'; END IF;\n  INSERT INTO public.edu_attendance(tenant_id,enrollment_id,status,roll_call_time)\n    VALUES(p_tenant_id,p_enrollment_id,p_status,p_roll_call_time) RETURNING edu_attendance.id INTO v_event_id;\n  INSERT INTO public.edu_attendance_daily_state(tenant_id,enrollment_id,school_day,status)\n    VALUES(p_tenant_id,p_enrollment_id,p_school_day,p_status)\n    ON CONFLICT ON CONSTRAINT edu_attendance_daily_state_unique\n    DO UPDATE SET status=EXCLUDED.status,updated_at=now() RETURNING * INTO v_state;\n  RETURN QUERY SELECT v_state.id,v_state.tenant_id,v_state.enrollment_id,v_state.school_day,v_state.status,\n    v_event_id,p_roll_call_time,v_state.created_at,v_state.updated_at;\nEND;\n$function$\n"},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"cceebaaeaf39cd21640880d0fbdb8963","owner":"postgres","config":["search_path=pg_catalog, public"],"definer":true,"signature":"get_auth_tenant_id()","definition":"CREATE OR REPLACE FUNCTION public.get_auth_tenant_id()\n RETURNS uuid\n LANGUAGE plpgsql\n STABLE SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public'\nAS $function$\nDECLARE\n  v_tenant_id uuid;\nBEGIN\n  SELECT u.tenant_id INTO v_tenant_id\n  FROM public.users AS u\n  JOIN public.tenants AS t ON t.id = u.tenant_id\n  WHERE u.id = auth.uid() AND u.status = 'active' AND t.status = 'active';\n\n  -- NULL would enable legacy policies using NULL as an unrestricted HQ sentinel.\n  IF v_tenant_id IS NULL THEN\n    RAISE EXCEPTION 'Active canonical identity and tenant required' USING ERRCODE = '42501';\n  END IF;\n  RETURN v_tenant_id;\nEND;\n$function$\n"},{"acl":"{=X/postgres,postgres=X/postgres,service_role=X/postgres}","md5":"beead9fad3f0d80f0a7580b32c104bce","owner":"postgres","config":null,"definer":true,"signature":"log_audit_event()","definition":"CREATE OR REPLACE FUNCTION public.log_audit_event()\n RETURNS trigger\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\nDECLARE\n    current_user_id UUID;\n    record_tenant_id UUID;\nBEGIN\n    BEGIN\n        current_user_id := auth.uid();\n    EXCEPTION WHEN OTHERS THEN\n        current_user_id := NULL;\n    END;\n    \n    BEGIN\n        IF TG_TABLE_NAME = 'tenants' THEN\n            IF TG_OP = 'DELETE' THEN\n                record_tenant_id := OLD.id;\n            ELSE\n                record_tenant_id := NEW.id;\n            END IF;\n        ELSE\n            IF TG_OP = 'DELETE' THEN\n                record_tenant_id := OLD.tenant_id;\n            ELSE\n                record_tenant_id := NEW.tenant_id;\n            END IF;\n        END IF;\n    EXCEPTION WHEN OTHERS THEN\n        record_tenant_id := NULL;\n    END;\n\n    BEGIN\n        INSERT INTO public.audit_logs (\n            tenant_id,\n            table_name,\n            record_id,\n            action,\n            old_data,\n            new_data,\n            changed_by_id\n        ) VALUES (\n            record_tenant_id,\n            TG_TABLE_NAME,\n            COALESCE(NEW.id, OLD.id),\n            TG_OP,\n            CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN row_to_json(OLD)::jsonb ELSE NULL END,\n            CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN row_to_json(NEW)::jsonb ELSE NULL END,\n            current_user_id\n        );\n    EXCEPTION WHEN OTHERS THEN\n        RAISE WARNING 'audit_log_event failed for table % op %: %', TG_TABLE_NAME, TG_OP, SQLERRM;\n    END;\n\n    IF TG_OP = 'DELETE' THEN\n        RETURN OLD;\n    ELSE\n        RETURN NEW;\n    END IF;\nEND;\n$function$\n"}],"relations":[{"acl":"{anon=r/postgres,authenticated=ar/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"audit_logs","owner":"postgres","forceRls":false,"definition":null},{"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"edu_attendance","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"edu_attendance_daily_state","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"edu_courses","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"edu_daily_care_records","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=ar/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"edu_daily_care_sessions","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"edu_enrollments","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=arwd/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"org_relationships","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=arwd/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"org_units","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"party_parties","owner":"postgres","forceRls":false,"definition":null},{"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"party_relationships","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=arwd/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"people_directory","owner":"postgres","forceRls":false,"definition":null},{"acl":"{postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"persons","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"preschool_chain_course_branch_assignments","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=arwd/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"students","owner":"postgres","forceRls":false,"definition":null},{"acl":"{anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"tenants","owner":"postgres","forceRls":false,"definition":null},{"acl":"{authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":false,"kind":"v","name":"user_org_unit_access","owner":"postgres","forceRls":false,"definition":" WITH RECURSIVE current_context AS (\n         SELECT COALESCE(auth.uid(), NULLIF(current_setting('app.current_user_id'::text, true), ''::text)::uuid) AS user_id,\n            COALESCE(get_auth_tenant_id(), NULLIF(current_setting('app.current_tenant_id'::text, true), ''::text)::uuid) AS tenant_id\n        ), direct_access AS (\n         SELECT pd.user_id,\n            rel.tenant_id,\n            rel.to_id AS org_unit_id,\n            rel.to_id AS root_org_unit_id,\n            rel.id AS relationship_id,\n            rel.rel_type AS access_source\n           FROM current_context ctx\n             JOIN people_directory pd ON pd.user_id = ctx.user_id AND pd.tenant_id = ctx.tenant_id AND pd.is_active = true\n             JOIN org_relationships rel ON rel.tenant_id = pd.tenant_id AND rel.from_id = pd.id AND rel.from_type = 'person'::text AND rel.to_type = 'unit'::text AND (rel.rel_type = ANY (ARRAY['belongs_to'::text, 'manages'::text, 'participates_in'::text])) AND (rel.since IS NULL OR rel.since <= CURRENT_DATE) AND (rel.until IS NULL OR rel.until >= CURRENT_DATE)\n             JOIN org_units ou ON ou.id = rel.to_id AND ou.tenant_id = rel.tenant_id AND ou.is_active = true\n        ), expanded_access AS (\n         SELECT direct_access.user_id,\n            direct_access.tenant_id,\n            direct_access.org_unit_id,\n            direct_access.root_org_unit_id,\n            direct_access.relationship_id,\n            direct_access.access_source\n           FROM direct_access\n        UNION\n         SELECT ea.user_id,\n            child.tenant_id,\n            child.id AS org_unit_id,\n            ea.root_org_unit_id,\n            ea.relationship_id,\n            ea.access_source\n           FROM expanded_access ea\n             JOIN org_units child ON child.parent_id = ea.org_unit_id AND child.tenant_id = ea.tenant_id AND child.is_active = true\n        ), admin_access AS (\n         SELECT u.id AS user_id,\n            ou.tenant_id,\n            ou.id AS org_unit_id,\n            ou.id AS root_org_unit_id,\n            NULL::uuid AS relationship_id,\n            'tenant_admin'::text AS access_source\n           FROM current_context ctx\n             JOIN users u ON u.id = ctx.user_id AND u.tenant_id = ctx.tenant_id AND (lower(u.role) = ANY (ARRAY['admin'::text, 'super_admin'::text]))\n             JOIN org_units ou ON ou.tenant_id = u.tenant_id AND ou.is_active = true\n        )\n SELECT DISTINCT expanded_access.user_id,\n    expanded_access.tenant_id,\n    expanded_access.org_unit_id,\n    expanded_access.root_org_unit_id,\n    expanded_access.relationship_id,\n    expanded_access.access_source\n   FROM expanded_access\nUNION\n SELECT DISTINCT admin_access.user_id,\n    admin_access.tenant_id,\n    admin_access.org_unit_id,\n    admin_access.root_org_unit_id,\n    admin_access.relationship_id,\n    admin_access.access_source\n   FROM admin_access;"},{"acl":"{anon=r/postgres,authenticated=r/postgres,postgres=arwdDxtm/postgres,service_role=arwdDxtm/postgres}","rls":true,"kind":"r","name":"users","owner":"postgres","forceRls":false,"definition":null}],"constraints":[{"name":"audit_logs_action_check","relation":"audit_logs","definition":"CHECK (action = ANY (ARRAY['INSERT'::text, 'UPDATE'::text, 'DELETE'::text]))"},{"name":"audit_logs_changed_by_id_fkey","relation":"audit_logs","definition":"FOREIGN KEY (changed_by_id) REFERENCES users(id) ON DELETE SET NULL"},{"name":"audit_logs_pkey","relation":"audit_logs","definition":"PRIMARY KEY (id)"},{"name":"audit_logs_tenant_id_fkey","relation":"audit_logs","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE"},{"name":"edu_attendance_enrollment_id_fkey","relation":"edu_attendance","definition":"FOREIGN KEY (enrollment_id) REFERENCES edu_enrollments(id) ON DELETE RESTRICT"},{"name":"edu_attendance_pkey","relation":"edu_attendance","definition":"PRIMARY KEY (id)"},{"name":"edu_attendance_status_check","relation":"edu_attendance","definition":"CHECK (status = ANY (ARRAY['present'::text, 'absent'::text, 'excused'::text]))"},{"name":"edu_attendance_tenant_id_fkey","relation":"edu_attendance","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT"},{"name":"edu_attendance_daily_state_enrollment_id_fkey","relation":"edu_attendance_daily_state","definition":"FOREIGN KEY (enrollment_id) REFERENCES edu_enrollments(id) ON DELETE RESTRICT"},{"name":"edu_attendance_daily_state_pkey","relation":"edu_attendance_daily_state","definition":"PRIMARY KEY (id)"},{"name":"edu_attendance_daily_state_status_check","relation":"edu_attendance_daily_state","definition":"CHECK (status = ANY (ARRAY['present'::text, 'absent'::text, 'excused'::text]))"},{"name":"edu_attendance_daily_state_tenant_id_fkey","relation":"edu_attendance_daily_state","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT"},{"name":"edu_attendance_daily_state_unique","relation":"edu_attendance_daily_state","definition":"UNIQUE (tenant_id, enrollment_id, school_day)"},{"name":"chk_edu_courses_capacity","relation":"edu_courses","definition":"CHECK (max_students IS NULL OR current_enrollment <= max_students)"},{"name":"chk_edu_courses_current_enrollment","relation":"edu_courses","definition":"CHECK (current_enrollment >= 0)"},{"name":"chk_edu_courses_max_students","relation":"edu_courses","definition":"CHECK (max_students IS NULL OR max_students > 0)"},{"name":"edu_courses_pkey","relation":"edu_courses","definition":"PRIMARY KEY (id)"},{"name":"edu_courses_status_check","relation":"edu_courses","definition":"CHECK (status = ANY (ARRAY['draft'::text, 'active'::text, 'archived'::text]))"},{"name":"edu_courses_tenant_id_fkey","relation":"edu_courses","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT"},{"name":"uq_edu_courses_code","relation":"edu_courses","definition":"UNIQUE (tenant_id, course_code)"},{"name":"edu_daily_care_records_arrival_status_check","relation":"edu_daily_care_records","definition":"CHECK (arrival_status = ANY (ARRAY['PRESENT'::text, 'ABSENT'::text, 'LATE'::text]))"},{"name":"edu_daily_care_records_pkey","relation":"edu_daily_care_records","definition":"PRIMARY KEY (id)"},{"name":"edu_daily_care_records_session_id_fkey","relation":"edu_daily_care_records","definition":"FOREIGN KEY (session_id) REFERENCES edu_daily_care_sessions(id) ON DELETE CASCADE"},{"name":"edu_daily_care_records_student_id_fkey","relation":"edu_daily_care_records","definition":"FOREIGN KEY (student_id) REFERENCES students(student_id) ON DELETE CASCADE"},{"name":"edu_daily_care_records_student_party_id_fkey","relation":"edu_daily_care_records","definition":"FOREIGN KEY (student_party_id) REFERENCES party_parties(id) ON DELETE CASCADE"},{"name":"edu_daily_care_records_tenant_id_fkey","relation":"edu_daily_care_records","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE"},{"name":"uq_session_student","relation":"edu_daily_care_records","definition":"UNIQUE (session_id, student_id)"},{"name":"edu_daily_care_sessions_pkey","relation":"edu_daily_care_sessions","definition":"PRIMARY KEY (id)"},{"name":"edu_daily_care_sessions_status_check","relation":"edu_daily_care_sessions","definition":"CHECK (status = ANY (ARRAY['OPEN'::text, 'COMPLETED'::text, 'CLOSED'::text]))"},{"name":"edu_daily_care_sessions_tenant_id_fkey","relation":"edu_daily_care_sessions","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE"},{"name":"uq_tenant_class_date","relation":"edu_daily_care_sessions","definition":"UNIQUE (tenant_id, class_id, date)"},{"name":"edu_enrollments_course_id_fkey","relation":"edu_enrollments","definition":"FOREIGN KEY (course_id) REFERENCES edu_courses(id) ON DELETE RESTRICT"},{"name":"edu_enrollments_pkey","relation":"edu_enrollments","definition":"PRIMARY KEY (id)"},{"name":"edu_enrollments_status_check","relation":"edu_enrollments","definition":"CHECK (status = ANY (ARRAY['pending'::text, 'active'::text, 'completed'::text, 'cancelled'::text]))"},{"name":"edu_enrollments_student_party_id_fkey","relation":"edu_enrollments","definition":"FOREIGN KEY (student_party_id) REFERENCES party_parties(id) ON DELETE RESTRICT"},{"name":"edu_enrollments_tenant_id_fkey","relation":"edu_enrollments","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT"},{"name":"uq_edu_enrollments_request_id","relation":"edu_enrollments","definition":"UNIQUE (tenant_id, request_id)"},{"name":"uq_edu_enrollments_student_course","relation":"edu_enrollments","definition":"UNIQUE (tenant_id, student_party_id, course_id)"},{"name":"org_relationships_from_type_check","relation":"org_relationships","definition":"CHECK (from_type = ANY (ARRAY['unit'::text, 'person'::text]))"},{"name":"org_relationships_pkey","relation":"org_relationships","definition":"PRIMARY KEY (id)"},{"name":"org_relationships_rel_type_check","relation":"org_relationships","definition":"CHECK (rel_type = ANY (ARRAY['belongs_to'::text, 'manages'::text, 'participates_in'::text, 'reports_to'::text, 'collaborates_with'::text]))"},{"name":"org_relationships_tenant_id_fkey","relation":"org_relationships","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE CASCADE"},{"name":"org_relationships_to_type_check","relation":"org_relationships","definition":"CHECK (to_type = ANY (ARRAY['unit'::text, 'person'::text]))"},{"name":