 ) AS evidence) s; IF actual IS DISTINCT FROM $dependency_expected${"columns":[{"name":"event_id","type":"uuid","default":"gen_random_uuid()","notNull":true},{"name":"tenant_id","type":"uuid","default":null,"notNull":true},{"name":"enrollment_id","type":"uuid","default":null,"notNull":true},{"name":"request_id","type":"text","default":null,"notNull":true},{"name":"event_type","type":"text","default":"'edu.enrollment.created.v1'::text","notNull":true},{"name":"event_version","type":"text","default":"'v1'::text","notNull":true},{"name":"occurred_at","type":"timestamp with time zone","default":null,"notNull":true},{"name":"payload","type":"jsonb","default":null,"notNull":true},{"name":"replay_state","type":"text","default":"'pending'::text","notNull":true},{"name":"replay_attempts","type":"integer","default":"0","notNull":true},{"name":"lease_token","type":"uuid","default":null,"notNull":false},{"name":"lease_until","type":"timestamp with time zone","default":null,"notNull":false},{"name":"last_error_code","type":"text","default":null,"notNull":false},{"name":"captured_at","type":"timestamp with time zone","default":"clock_timestamp()","notNull":true}],"policies":null,"relation":{"acl":"{postgres=arwdDxtm/postgres}","rls":true,"name":"edu_enrollment_event_records","owner":"postgres"},"triggers":[],"functions":[{"acl":"{postgres=X/postgres,service_role=X/postgres,authenticated=X/postgres}","signature":"preschool_branch_access(uuid,uuid,uuid,text)","definition":"CREATE OR REPLACE FUNCTION public.preschool_branch_access(p_tenant_id uuid, p_actor_id uuid, p_branch_id uuid, p_action text DEFAULT 'registry'::text)\n RETURNS boolean\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'pg_catalog', 'public', 'pg_temp'\nAS $function$\nDECLARE v_role text; v_allowed boolean;\nBEGIN\n  IF p_actor_id IS NULL OR (auth.role() IS DISTINCT FROM 'service_role' AND auth.uid() IS DISTINCT FROM p_actor_id) THEN RETURN false; END IF;\n  SELECT lower(u.role) INTO v_role FROM public.users u JOIN public.tenants t ON t.id=u.tenant_id\n    JOIN auth.users a ON a.id=u.id WHERE u.id=p_actor_id AND u.tenant_id=p_tenant_id\n      AND u.status='active' AND t.status='active' AND a.deleted_at IS NULL\n      AND (a.banned_until IS NULL OR a.banned_until<=clock_timestamp());\n  IF v_role IS NULL OR (p_action='admission' AND v_role NOT IN ('admin','super_admin'))\n    OR (p_action IN ('registry','attendance') AND v_role NOT IN ('admin','super_admin','admin_staff'))\n    OR p_action IS NULL OR p_action NOT IN ('admission','registry','attendance') THEN RETURN false; END IF;\n  IF NOT EXISTS(SELECT 1 FROM public.org_units WHERE id=p_branch_id AND tenant_id=p_tenant_id\n    AND unit_type='branch' AND is_active=true) THEN RETURN false; END IF;\n  IF auth.role()='service_role' THEN\n    -- Service writers accept only current canonical tenant administrators.\n    -- Their tenant-wide active-unit scope is the existing Platform admin rule.\n    RETURN v_role IN ('admin','super_admin');\n  END IF;\n  SELECT EXISTS(SELECT 1 FROM public.user_org_unit_access WHERE user_id=auth.uid()\n    AND tenant_id=p_tenant_id AND org_unit_id=p_branch_id) INTO v_allowed;\n  RETURN v_allowed;\nEND;\n$function$\n"}],"constraints":[{"name":"edu_enrollment_event_records_event_type_check","table":"edu_enrollment_event_records","definition":"CHECK (event_type = 'edu.enrollment.created.v1'::text)"},{"name":"edu_enrollment_event_records_event_version_check","table":"edu_enrollment_event_records","definition":"CHECK (event_version = 'v1'::text)"},{"name":"edu_enrollment_event_records_payload_check","table":"edu_enrollment_event_records","definition":"CHECK (jsonb_typeof(payload) = 'object'::text)"},{"name":"edu_enrollment_event_records_replay_state_check","table":"edu_enrollment_event_records","definition":"CHECK (replay_state = ANY (ARRAY['pending'::text, 'leased'::text, 'retryable'::text, 'intervention_required'::text]))"},{"name":"edu_enrollment_event_records_replay_attempts_check","table":"edu_enrollment_event_records","definition":"CHECK (replay_attempts >= 0 AND replay_attempts <= 5)"},{"name":"edu_enrollment_event_records_last_error_code_check","table":"edu_enrollment_event_records","definition":"CHECK (last_error_code ~ '^[A-Z0-9_]{1,80}$'::text)"},{"name":"edu_enrollment_event_records_check","table":"edu_enrollment_event_records","definition":"CHECK ((replay_state = 'leased'::text) = (lease_token IS NOT NULL AND lease_until IS NOT NULL))"},{"name":"edu_enrollment_event_records_check1","table":"edu_enrollment_event_records","definition":"CHECK (replay_state = 'leased'::text OR lease_token IS NULL AND lease_until IS NULL)"},{"name":"edu_enrollment_event_records_pkey","table":"edu_enrollment_event_records","definition":"PRIMARY KEY (event_id)"},{"name":"edu_enrollment_event_records_tenant_id_enrollment_id_key","table":"edu_enrollment_event_records","definition":"UNIQUE (tenant_id, enrollment_id)"},{"name":"edu_enrollment_event_records_tenant_id_request_id_key","table":"edu_enrollment_event_records","definition":"UNIQUE (tenant_id, request_id)"},{"name":"edu_enrollment_event_records_tenant_id_fkey","table":"edu_enrollment_event_records","definition":"FOREIGN KEY (tenant_id) REFERENCES tenants(id) ON DELETE RESTRICT"},{"name":"edu_enrollment_event_records_enrollment_id_fkey","table":"edu_enrollment_event_records","definition":"FOREIGN KEY (enrollment_id) REFERENCES edu_enrollments(id) ON DELETE RESTRICT"},{"name":"edu_enrollment_event_replays_event_id_fkey","table":"edu_enrollment_event_replays","definition":"FOREIGN KEY (event_id) REFERENCES edu_enrollment_event_records(event_id) ON DELETE RESTRICT"}]}$dependency_expected$::jsonb THEN RAISE EXCEPTION 'READONLY_DEPENDENCY_DRIFT:E2E_BOUNDARY'; END IF; END $dependency$;
